"use client";

import { useEffect, useRef, useState } from "react";
import {
  buildGazeMessage,
  findLookTarget,
  startExpressionDetection,
} from "../utils/utils";

const IDLE_GAZE_MESSAGE =
  "Click Detect face. Look at the center dot for a moment, then look around the screen.";

function readLookRegions(root) {
  return [...root.querySelectorAll("[data-look]")].map((element) => {
    const rect = element.getBoundingClientRect();
    return {
      name: element.dataset.look,
      left: rect.left,
      top: rect.top,
      right: rect.right,
      bottom: rect.bottom,
    };
  });
}

export default function FaceExpression() {
  const pageRef = useRef(null);
  const videoRef = useRef(null);
  const sessionRef = useRef(null);

  const [expression, setExpression] = useState("Detection is off");
  const [error, setError] = useState("");
  const [isRunning, setIsRunning] = useState(false);
  const [isStarting, setIsStarting] = useState(false);
  const [gaze, setGaze] = useState(null);
  const [activeLook, setActiveLook] = useState("");
  const [lookMessage, setLookMessage] = useState(IDLE_GAZE_MESSAGE);

  useEffect(() => () => sessionRef.current?.stop(), []);

  function updateGazeMessage(nextGaze) {
    if (!nextGaze) {
      setActiveLook("");
      setLookMessage("No face detected, so I can't see where your eyes are looking.");
      return;
    }

    if (nextGaze.calibrating) {
      setActiveLook("");
      setLookMessage("Look at the center of the screen while your eyes are measured.");
      return;
    }

    const regions = pageRef.current ? readLookRegions(pageRef.current) : [];
    const target = findLookTarget(nextGaze.x, nextGaze.y, regions, {
      width: window.innerWidth,
      height: window.innerHeight,
    });

    setActiveLook(target?.name ?? "");
    setLookMessage(
      buildGazeMessage({
        targetName: target?.name,
        x: nextGaze.x,
        y: nextGaze.y,
      })
    );
  }

  function start() {
    const video = videoRef.current;
    if (!video || sessionRef.current) return;

    setError("");
    setIsStarting(true);
    setExpression("Starting camera...");
    setLookMessage("Starting camera...");

    sessionRef.current = startExpressionDetection({
      video,
      onRunning: () => {
        setIsStarting(false);
        setIsRunning(true);
      },
      onUpdate: ({ expression: nextExpression, gaze: nextGaze }) => {
        setExpression(nextExpression);
        setGaze(nextGaze);
        updateGazeMessage(nextGaze);
      },
      onError: (message) => {
        sessionRef.current?.stop();
        sessionRef.current = null;
        setIsStarting(false);
        setIsRunning(false);
        setGaze(null);
        setActiveLook("");
        setExpression("Detection is off");
        setLookMessage(IDLE_GAZE_MESSAGE);
        setError(message);
      },
    });
  }

  function stop() {
    sessionRef.current?.stop();
    sessionRef.current = null;
    setIsStarting(false);
    setIsRunning(false);
    setGaze(null);
    setActiveLook("");
    setExpression("Detection is off");
    setLookMessage(IDLE_GAZE_MESSAGE);
  }

  function recenter() {
    sessionRef.current?.recenter();
    setLookMessage("Look at the center of the screen while your eyes are measured.");
  }

  function targetClass(name) {
    return activeLook === name
      ? "ring-2 ring-sky-500 ring-offset-2 ring-offset-white dark:ring-offset-neutral-950"
      : "";
  }

  return (
    <main
      ref={pageRef}
      className="mx-auto flex min-h-screen w-full max-w-5xl flex-col gap-4 p-4 md:p-6"
    >
      <header className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
        <div data-look="the title" className={`rounded-2xl ${targetClass("the title")}`}>
          <h1 className="text-2xl font-bold">AI Face Expression Detection</h1>
          <p className="mt-1 max-w-xl text-sm text-neutral-500">
            Start the camera, then look around. The page names whatever your eyes are on.
          </p>
        </div>

        <button
          type="button"
          data-look="the detect button"
          onClick={isRunning ? stop : start}
          disabled={isStarting}
          className={`rounded-full px-5 py-2.5 text-sm font-semibold transition disabled:opacity-60 ${targetClass("the detect button")} ${
            isRunning
              ? "bg-red-600 text-white"
              : "bg-neutral-900 text-white dark:bg-white dark:text-neutral-900"
          }`}
        >
          {isStarting ? "Starting camera..." : isRunning ? "Stop detection" : "Detect face"}
        </button>
      </header>

      <section className="grid flex-1 gap-4 md:grid-cols-[1.4fr_0.9fr]">
        <div
          data-look="the camera preview"
          className={`relative overflow-hidden rounded-2xl bg-black ${targetClass("the camera preview")}`}
        >
          <video
            ref={videoRef}
            autoPlay
            muted
            playsInline
            className="aspect-[4/3] w-full -scale-x-100 object-cover"
          />
          {!isRunning && (
            <div className="absolute inset-0 flex items-center justify-center bg-neutral-950/80 px-6 text-center text-sm text-white">
              Camera is off. Click Detect face to begin.
            </div>
          )}
        </div>

        <div className="flex flex-col gap-4">
          <article
            data-look="the expression result"
            className={`rounded-2xl border border-neutral-200 p-4 dark:border-neutral-800 ${targetClass("the expression result")}`}
          >
            <p className="text-sm text-neutral-500">Detected expression</p>
            <p className="mt-2 text-2xl font-semibold">{expression}</p>
            {isRunning && (
              <p className="mt-2 text-sm text-green-600">Camera is running</p>
            )}
            {error && <p className="mt-2 text-sm text-red-500">{error}</p>}
          </article>

          <article
            data-look="the eye direction message"
            className={`flex flex-1 flex-col rounded-2xl border border-neutral-200 p-4 dark:border-neutral-800 ${targetClass("the eye direction message")}`}
          >
            <p className="text-sm text-neutral-500">Where you are looking</p>
            <p className="mt-2 text-xl font-semibold leading-snug" aria-live="polite">
              {lookMessage}
            </p>
            {isRunning && !gaze?.calibrating && (
              <button
                type="button"
                data-look="the recenter button"
                onClick={recenter}
                className={`mt-4 w-fit rounded-full border border-neutral-300 px-4 py-2 text-sm font-medium dark:border-neutral-700 ${targetClass("the recenter button")}`}
              >
                Recenter eyes
              </button>
            )}
          </article>
        </div>
      </section>

      {isRunning && gaze?.calibrating && (
        <div className="pointer-events-none fixed top-1/2 left-1/2 z-40 -translate-x-1/2 -translate-y-1/2 text-center">
          <div className="mx-auto size-5 rounded-full border-2 border-sky-500 bg-white shadow" />
          <p className="mt-2 rounded-full bg-neutral-950/80 px-3 py-1 text-sm text-white">
            Look here
          </p>
        </div>
      )}

      {isRunning && gaze && !gaze.calibrating && (
        <div
          aria-hidden
          className="pointer-events-none fixed z-50 size-7 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-white bg-sky-500/80 shadow-lg"
          style={{ left: `${gaze.x * 100}%`, top: `${gaze.y * 100}%` }}
        />
      )}
    </main>
  );
}
